-- Keep historical completions and immutable run receipts while retiring four cards.
begin;
alter table public.phd_simulator_v2_achievement_catalog
  add column if not exists active boolean not null default true;

-- BEGIN GENERATED ACHIEVEMENT CATALOG
-- 175 achievements, 18 roles; generated by scripts/sync-achievement-stat-catalog.mjs
on conflict (id) do update set eligible_role_ids = excluded.eligible_role_ids, active = true;
-- END GENERATED ACHIEVEMENT CATALOG

update public.phd_simulator_v2_achievement_catalog set active = false
where id in ('global:no-first-conference-graduation', 'global:help-collector', 'global:balanced-company', 'global:travel-kit');

create or replace function public.record_phd_simulator_v2_achievement_run(
  p_player_id uuid, p_run_id uuid, p_role_id text, p_achievement_ids text[], p_epoch text default null
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  normalized_ids text[];
  existing_ids text[];
  retired_ids constant text[] := array['global:no-first-conference-graduation', 'global:help-collector', 'global:balanced-company', 'global:travel-kit'];
  existing_run public.phd_simulator_v2_achievement_runs%rowtype;
  inserted_id uuid;
begin
  if p_epoch is distinct from '20261016-monthly-replay-v1' then raise exception 'Refresh the game: achievement epoch expired' using errcode = '22023'; end if;
  if p_player_id is null or p_run_id is null
    or p_player_id::text !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or p_run_id::text !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or p_role_id is null
    or not exists (select 1 from public.phd_simulator_v2_achievement_catalog c where c.active and p_role_id = any(c.eligible_role_ids))
    or p_achievement_ids is null or cardinality(p_achievement_ids) > 512
    or exists (select 1 from pg_catalog.unnest(p_achievement_ids) a(id) where a.id is null) then
    raise exception 'Invalid achievement run' using errcode = '22023';
  end if;

  -- Old clients/outboxes can still contain the four retired IDs. Ignore only
  -- these known IDs; unknown IDs and invalid role scopes remain errors.
  select coalesce(pg_catalog.array_agg(a.id order by a.id), '{}'::text[])
    into normalized_ids from (select distinct id from pg_catalog.unnest(p_achievement_ids) u(id)
      where not (id = any(retired_ids))) a;
  if exists (
    select 1 from pg_catalog.unnest(normalized_ids) a(id)
    where not exists (select 1 from public.phd_simulator_v2_achievement_catalog c
      where c.active and c.id = a.id and p_role_id = any(c.eligible_role_ids))
  ) then
    raise exception 'Unknown achievement or ineligible role' using errcode = '22023';
  end if;

    values (p_run_id, p_player_id, p_role_id, normalized_ids, '20261016-monthly-replay-v1')
    on conflict (id) do nothing returning id into inserted_id;
  if inserted_id is null then
    select * into existing_run from public.phd_simulator_v2_achievement_runs where id = p_run_id for update;
    select coalesce(pg_catalog.array_agg(a.id order by a.id), '{}'::text[])
      into existing_ids from (select distinct id from pg_catalog.unnest(existing_run.achievement_ids) u(id)
        where not (id = any(retired_ids))) a;
    if existing_run.data_epoch <> '20261016-monthly-replay-v1' or existing_run.player_id is distinct from p_player_id
      or existing_run.role_id is distinct from p_role_id or existing_ids is distinct from normalized_ids then
      raise exception 'Finalized achievement run cannot be changed' using errcode = '22023';
    end if;
    return true;
  end if;

    select p_player_id, a.id, p_role_id, '20261016-monthly-replay-v1' from pg_catalog.unnest(normalized_ids) a(id)
    on conflict (player_id, achievement_id, role_id) do update set data_epoch = excluded.data_epoch, completed_at = pg_catalog.now()
      where public.phd_simulator_v2_achievement_completions.data_epoch <> excluded.data_epoch;
  return true;
end;
$$;

create or replace function public.get_phd_simulator_v2_achievement_stats_v2()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with started as (
    select count(*) as players from public.phd_simulator_v2_achievement_players
    where data_epoch = '20261016-monthly-replay-v1' and first_recorded_at >= timestamptz '2026-10-16T05:25:29.000Z'
  ), valid_completions as (
    select a.player_id, a.achievement_id
    from public.phd_simulator_v2_achievement_completions a
    join public.phd_simulator_v2_achievement_catalog c on c.id = a.achievement_id and c.active
      and a.role_id = any(c.eligible_role_ids)
    where a.data_epoch = '20261016-monthly-replay-v1' and a.completed_at >= timestamptz '2026-10-16T05:25:29.000Z'
      and exists (select 1 from public.phd_simulator_v2_achievement_players p where p.player_id = a.player_id
        and p.data_epoch = '20261016-monthly-replay-v1' and p.first_recorded_at >= timestamptz '2026-10-16T05:25:29.000Z')
  ), achieved as (
    select achievement_id, count(distinct player_id) as players from valid_completions group by achievement_id
  ), display_rows as (
    select c.id, coalesce(a.players, 0) as players
    from public.phd_simulator_v2_achievement_catalog c left join achieved a on a.achievement_id = c.id
    where c.active
  )
  select pg_catalog.jsonb_build_object('version', 2, 'epoch', '20261016-monthly-replay-v1', 'achievements',
    coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'id', d.id, 'achievedPlayers', d.players, 'eligiblePlayers', s.players
    ) order by d.id), '[]'::jsonb))
  from display_rows d cross join started s;
$$;

revoke all on function public.record_phd_simulator_v2_achievement_run(uuid, uuid, text, text[], text) from public, anon, authenticated;
grant execute on function public.record_phd_simulator_v2_achievement_run(uuid, uuid, text, text[], text) to anon, authenticated;
notify pgrst, 'reload schema';
commit;
